SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b209265fbe734c2fa40aacb570f4fd3aa12504d1/content/books/zizhi-tongjian/vol-293/year-0956/part-04/sources/library/jiuwudaishi-116-june-south-camp/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002757；EPUB电子本，纸本及异文待核", "id": "7a3ecb9f-07b4-5632-9a33-4ca597f33d1e"}, {"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b209265fbe734c2fa40aacb570f4fd3aa12504d1/content/books/zizhi-tongjian/vol-293/year-0956/part-04/sources/library/jiuwudaishi-116-may-956/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002756；EPUB电子本，纸本及异文待核", "id": "6520297c-1ce0-5dae-b26d-bad3b415736e"}, {"title": "宋史·巻二百五十四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b209265fbe734c2fa40aacb570f4fd3aa12504d1/content/books/zizhi-tongjian/vol-293/year-0956/part-04/sources/library/songshi-254-lijixun-identity/source.txt", "note": "《宋史》巻二百五十四，段落 songshi-9c6e46fee832-p057495；EPUB电子本，纸本及异文待核", "id": "ab0708d4-f3ef-5bd0-b4c0-735d90d90ebf"}, {"title": "宋史·巻二百五十五", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b209265fbe734c2fa40aacb570f4fd3aa12504d1/content/books/zizhi-tongjian/vol-293/year-0956/part-04/sources/library/songshi-255-zhangyongde-quxi/source.txt", "note": "《宋史》巻二百五十五，段落 songshi-9c6e46fee832-p057598；EPUB电子本，纸本及异文待核", "id": "74a65af8-ff1f-5e4a-9fef-298b21dc3ec4"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b209265fbe734c2fa40aacb570f4fd3aa12504d1/content/books/zizhi-tongjian/vol-293/year-0956/part-04/sources/library/tongjian-293-956-may-june/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003478；电子底本待考，分段待核", "id": "1220fd4d-93ea-552d-9a8c-619a04a2ec85"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/32533eed18a7fca71281bc84f91c0f9a586b003c/content/books/zizhi-tongjian/vol-293/year-0956/part-03/sources/library/tongjian-293-956-april-yangzhou-liuhe/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003477；电子底本待考，分段待核", "id": "7347b9e9-a086-5c4d-9248-c37e6dbe7b0b"}, {"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/32533eed18a7fca71281bc84f91c0f9a586b003c/content/books/zizhi-tongjian/vol-293/year-0956/part-03/sources/library/jiuwudaishi-116-april-yangzhou-liuhe/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002755；EPUB电子本，纸本及异文待核", "id": "3b9dc74a-ebf9-5ac4-826b-516718d20629"}]'::jsonb)
