INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "韩令坤", "aliases": ["韓令坤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "磁州武安人，后周侍卫马军都指挥使。955年十一月，奉柴荣命与其他十一名将领随李谷、王彦超出征南唐。生卒年未载。", "biography": null, "status": "draft", "id": "808ffe02-5578-55cc-8c1f-2b9823cfd253"}, {"name": "秦进崇", "aliases": ["秦進崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐涟州刺史。956年四月韩令坤奏报在湾头堰击败楚州兵时，被俘获。生卒年未载。", "biography": null, "status": "draft", "id": "36297cd8-a9ac-5add-b8d3-f3af6785298b"}, {"name": "马在贵", "aliases": ["馬在貴"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐楚州将领。956年四月在湾头堰被韩令坤击败，《旧五代史》记其所领万余众，未记其本人最后结局。生卒年未载。", "biography": null, "status": "draft", "id": "2e1e59d2-9823-5c5d-a3ad-959cb358f792"}, {"name": "张永德", "aliases": ["張永德"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "阳曲人，郭威的女婿。950年任供奉官押班，奉命给昭义节度使常思送生日礼物；常思接到杀他的密诏后拘留观望，郭威取京师后释放并道歉。生卒年本批未录。", "biography": null, "status": "draft", "id": "c1584e5c-2a3c-5c28-bbe4-7c8a05161c51"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}, {"name": "范质", "aliases": ["范質", "範質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宗城人，后晋主客员外郎。944年六月戊辰任翰林学士。后续仕宦随编年主线补录。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "abe2c0af-4bf3-551b-83c9-f355ba085a0e"}, {"name": "窦仪", "aliases": ["竇儀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蓟州人，后晋天平军观察判官。944年正月奉颜衎命向朝廷奏报周儒降契丹、引兵渡河及蔡行遇被俘，并向景延广说明与杨光远会合的危险。生卒年本批未核。", "biography": null, "status": "draft", "id": "9d318328-3904-5714-a390-ea527c3e9fd9"}, {"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "陈诲", "aliases": ["陳誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "建安人，王延政麾下战棹都头。940年三月在夜袭中杀死潘师逵。生卒年未载。", "biography": null, "status": "draft", "id": "8c18058e-c4f8-52ab-a4d2-9caaba34336a"}, {"name": "陈德诚", "aliases": ["陳德誠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "静江指挥使。956年南唐潘承祐在泉建募兵时举荐，随后陆孟俊恢复泰州，派其戍守。生卒年未载。", "biography": null, "status": "draft", "id": "5c0f3a0f-e33c-5bb5-bed7-26075de15f3b"}, {"name": "李重进", "aliases": ["李重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沧州人，福庆长公主之子，郭威的外甥，生于太原。郭威在藩镇时期的将佐，952年任恩州团练使，逐渐受重用。《宋史》还记当年内殿职务变化，具体任日未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9769d0fb-1d80-593e-9aa3-e4c22416f835"}, {"name": "李继勋（后周宋初将领）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "大名元城人，后周侍卫步军都指挥使、彰信节度使。956年六月驻寿州城南，被刘仁赡趁无备突击，南寨受损。《宋史》记其早年在郭威帐下任禁军官。与947年后蜀同名左千牛卫上将军缺少同人证据，分别保存。", "biography": null, "status": "draft", "id": "5f69fa08-5e14-59cf-aa6f-05cbc3b5001b"}, {"name": "刘仁赡", "aliases": ["劉仁贍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领，刘金之子，字守惠、彭城人。951年以武昌节度使身份率二百艘战舰攻取岳州。《新五代史》还记他早年任左监门卫将军、黄袁二州刺史，后掌亲军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "fbdf8a53-b985-5dda-a5d1-e96cf9d7121c"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "赵匡胤在六合战中斫不尽力士卒的皮笠，次日查痕处死数十人", "start_year": 956, "end_year": 956, "time_original": "956年四月六合交战及次日，具体日未载", "dynasty": "五代十国", "description": "《通鉴》记赵匡胤假作督战，斫不尽力士卒的皮笠作记号，次日查验有刀痕者数十人并处死。随后部下不敢不拼力作战。不尽死在此为尽力效死，不是全军已经死亡。", "phases": [], "location_name": "六合周军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "471490a6-6acb-5700-9525-5ac0e6607f05"}, {"title": "李璟闻扬州失守，命周边各处发兵收复", "start_year": 956, "end_year": 956, "time_original": "956年二月扬州失守之后的回述，具体发令日未载", "dynasty": "五代十国", "description": "李璟闻扬州失守，命周边各处发兵收复。", "phases": [], "location_name": "南唐周边至扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "bc821b05-be8c-572f-84d3-af45e7a571fb"}, {"title": "韩令坤奏报湾头堰击败楚州兵万余，俘秦进崇", "start_year": 956, "end_year": 956, "time_original": "956年四月己卯奏报，交战日未单列", "dynasty": "五代十国", "description": "韩令坤奏报湾头堰击败楚州兵万余，俘秦进崇。", "phases": [], "location_name": "湾头堰", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "275020fb-2d94-5fd3-b2af-35c19cafc938"}, {"title": "张永德奏报在曲溪堰击败万余泗州兵", "start_year": 956, "end_year": 956, "time_original": "956年四月己卯条所附奏报，独立交战日未载", "dynasty": "五代十国", "description": "张永德奏报在曲溪堰击败万余泗州兵。", "phases": [], "location_name": "曲溪堰", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b7f8f33b-65f2-586b-8d3f-352923062112"}, {"title": "柴荣任向训为淮南节度使兼沿江招讨使", "start_year": 956, "end_year": 956, "time_original": "956年四月丙戌", "dynasty": "五代十国", "description": "柴荣任向训为淮南节度使兼沿江招讨使。", "phases": [], "location_name": "淮南及沿江", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "67de55aa-17d2-50fa-a7b1-9cb4501906b7"}, {"title": "涡口奏报新建浮桥完成", "start_year": 956, "end_year": 956, "time_original": "956年四月丙戌条所记奏报，竣工日未另列", "dynasty": "五代十国", "description": "涡口奏报新建浮桥完成。", "phases": [], "location_name": "涡口", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f9487f6e-cb42-59d2-b479-d0fa36163010"}, {"title": "柴荣由濠州到涡口", "start_year": 956, "end_year": 956, "time_original": "956年四月丁亥", "dynasty": "五代十国", "description": "柴荣由濠州到涡口。", "phases": [], "location_name": "濠州至涡口", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ea0126e2-9ec7-55dd-9f46-869254a93129"}, {"title": "柴荣想亲去扬州，范质等以兵疲粮少哭谏，柴荣止行", "start_year": 956, "end_year": 956, "time_original": "956年四月在涡口期间，具体谏止日未载", "dynasty": "五代十国", "description": "柴荣想亲去扬州，范质等以兵疲粮少哭谏，柴荣止行。", "phases": [], "location_name": "涡口", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4dbe45f7-99f9-5ee0-aa13-013a4ff9c658"}, {"title": "柴荣曾因生气欲杀窦仪，范质赶来劝救", "start_year": null, "end_year": null, "time_original": "柴荣在位期间的回述，具体年日未载", "dynasty": "五代十国", "description": "柴荣曾因生气欲杀窦仪，范质赶来劝救。", "phases": [], "location_name": "后周朝廷，具体地点未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "715d4c