SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "《通鉴》记赵匡胤假作督战，斫不尽力士卒的皮笠作记号，次日查验有刀痕者数十人并处死。随后部下不敢不拼力作战。不尽死在此为尽力效死，不是全军已经死亡。", "citation": "卷293·显德三年（956年四月至六月及相关追述）·zztj-v293-y0956-p025·原文件第30行", "note": "原文：是战也，士卒有不致力者。太祖皇帝阳为督战，以剑斫其皮笠。明日，遍阅其皮笠，有剑亦者数十人，皆斩之，由是部兵莫敢不尽死，；核对说明：底本有剑亦字形异常，按斫笠再检叙事解释为痕迹，原文保留；人员名单和精确人数未载。", "status": "draft", "id": "1604df21-cf61-52c3-8331-8f57ce5a3868", "subject_id": "471490a6-6acb-5700-9525-5ac0e6607f05", "source_id": "7347b9e9-a086-5c4d-9248-c37e6dbe7b0b"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "956年四月六合交战及次日，具体日未载", "citation": "卷293·显德三年（956年四月至六月及相关追述）·zztj-v293-y0956-p025·原文件第30行", "note": "原文：是战也，士卒有不致力者。太祖皇帝阳为督战，以剑斫其皮笠。明日，遍阅其皮笠，有剑亦者数十人，皆斩之，由是部兵莫敢不尽死，；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "ab7e4ab6-01ee-50d2-85d1-89cf0dd4363e", "subject_id": "471490a6-6acb-5700-9525-5ac0e6607f05", "source_id": "7347b9e9-a086-5c4d-9248-c37e6dbe7b0b"}, {"subject_table": "person", "field_path": "description", "claim_text": "赵匡胤：以斫笠作记号，次日检笠后杀不尽力士卒。", "citation": "卷293·显德三年（956年四月至六月及相关追述）·zztj-v293-y0956-p025·原文件第30行", "note": "原文：是战也，士卒有不致力者。太祖皇帝阳为督战，以剑斫其皮笠。明日，遍阅其皮笠，有剑亦者数十人，皆斩之，由是部兵莫敢不尽死，；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "afbd6b98-cd6f-5973-bcca-efd814c62acd", "subject_id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad", "source_id": "7347b9e9-a086-5c4d-9248-c37e6dbe7b0b"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "赵匡胤：以斫笠作记号，次日检笠后杀不尽力士卒。", "citation": "卷293·显德三年（956年四月至六月及相关追述）·zztj-v293-y0956-p025·原文件第30行", "note": "原文：是战也，士卒有不致力者。太祖皇帝阳为督战，以剑斫其皮笠。明日，遍阅其皮笠，有剑亦者数十人，皆斩之，由是部兵莫敢不尽死，；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "a1f027c3-f0e3-56c6-8c8b-f35161c5d92f", "subject_id": "9da9efda-89f6-5229-80bf-9a36cfd1fdc7", "source_id": "7347b9e9-a086-5c4d-9248-